export type SymbolName = keyof typeof SYMBOLS;

/** An SF Symbol, filled with the current text color and fit into the box the class sets. */
export function SFSymbol({ name, ...props }: { name: SymbolName } & SVGProps<SVGSVGElement>) {
    const [viewBox, d] = SYMBOLS[name];
    return (
        <svg viewBox={viewBox} fill="currentColor" aria-hidden {...props}>
            <path d={d} />
        </svg>
    );
}
